import {uid,day,rub,parse,sign,balance,remaining,planned,total,demo,urgency,daysUntil,isReminder,nextMonth,putEntry,removeEntry,payPlan,monthKey,currentMonth,monthlyReport,reportMonths,searchEntries,debtSummary,editDebt,deleteDebt} from './core.js?v=7';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='moy-wallet-v1';let state,readError=false;
try {const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):demo();if(!valid(state))throw Error('schema');if(!state.reportStart){state.reportStart=[currentMonth(),...state.entries.map(e=>monthKey(e.date))].sort()[0];localStorage.setItem(KEY,JSON.stringify(state))}else if(!raw)localStorage.setItem(KEY,JSON.stringify(state))}catch{state=demo();readError=true}
function valid(s){return s?.version===1&&Number.isSafeInteger(s.opening)&&['entries','debts','plans','categories'].every(k=>Array.isArray(s[k]))&&s.entries.every(e=>typeof e.id==='string'&&Number.isSafeInteger(e.amount)&&e.amount>0&&['expense','income','lent','borrowed','returned','repaid'].includes(e.kind)&&validDate(e.date)&&typeof e.category==='string')&&s.debts.every(d=>typeof d.id==='string'&&typeof d.person==='string'&&typeof d.lent==='boolean')&&s.categories.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&typeof c.emoji==='string'&&typeof c.income==='boolean')&&s.plans.every(p=>typeof p.id==='string'&&typeof p.title==='string'&&Number.isSafeInteger(p.amount)&&p.amount>0&&validDate(p.date)&&Number.isInteger(p.anchor)&&p.anchor>=1&&p.anchor<=31)&&s.debts.every(d=>remaining(s,d.id)>=0)}
function validDate(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(Date.parse(d+'T12:00:00'))}
function change(fn){const previous=structuredClone(state);try{if(readError)throw Error('Сохранение недоступно. Сначала экспортируйте данные и проверьте доступ к хранилищу в настройках браузера.');fn();localStorage.setItem(KEY,JSON.stringify(state));render();return true}catch(e){state=previous;showError(e.message);return false}}
let route=(location.hash.slice(1)||'home'),filter='all',draft=null,reportQuery='',reportFilter='all';const modal=$('#modal');
const navs=[['home','⌂','Главная'],['debts','♧','Долги'],['plans','▦','Планы'],['reports','▤','Отчёты'],['settings','⚙','Настройки']];
const formatDate=(d,year=false)=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long',...(year?{year:'numeric'}:{})});
const labelKind=k=>({expense:'Расход',income:'Доход',lent:'Дал в долг',borrowed:'Взял в долг',returned:'Мне вернули',repaid:'Вернул долг'}[k]);
const emoji=s=>Array.from(s||'✨')[0];
const amountText=n=>(n/100).toString().replace('.',',');
const act=(action,text,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function showError(text){const el=$('#form-error');if(modal.open&&el){el.textContent=text;el.scrollIntoView({block:'nearest'})}else toast(text)}
function header(title,sub='ЛИЧНЫЕ ФИНАНСЫ'){return `<header class="topline"><div><div class="eyebrow">${sub}</div><h1>${title}</h1></div><div class="header-right"><span class="date-top">${formatDate(day())}</span><button type="button" class="avatar" data-action="navigate" data-route="settings" aria-label="Настройки">МК</button></div></header>`}
function row(e){return `<button class="entry-row entry-${e.kind==='income'?'income':e.kind==='expense'?'expense':'debt'}" data-action="entry" data-id="${e.id}"><span class="emoji">${esc(emoji(e.category))}</span><span class="entry-info"><strong>${esc(e.debtId?labelKind(e.kind):e.category.replace(/^\S+\s/,''))}</strong><small>${esc(labelKind(e.kind))}${e.note?' · '+esc(e.note):''}</small></span><span class="entry-right"><strong class="${sign(e.kind)>0?'positive':''}">${sign(e.kind)>0?'+':'−'}${rub(e.amount)}</strong><small>${formatDate(e.date)}</small></span></button>`}
function historyRows(entries=monthlyReport(state,currentMonth()).entries){const list=entries.filter(e=>filter==='all'||(filter==='income'?e.kind==='income':filter==='expense'?e.kind==='expense':e.debtId)).sort((a,b)=>b.date.localeCompare(a.date)||b.created-a.created);return list.length?list.map(row).join(''):'<div class="empty">Здесь пока нет операций</div>'}
function historySection(full=false){return `<section class="history"><div class="section-title"><h2>${full?'Все операции':'Операции за месяц'}</h2><div class="history-controls">${[['all','Все'],['income','Доходы'],['expense','Расходы'],['debt','Долги']].map(([id,label])=>act('filter',label,`chip ${filter===id?'active':''}`,`data-value="${id}"`)).join('')}</div></div><div class="history-list">${carryRow(currentMonth())}${historyRows()}</div><div class="history-foot">Новые сверху · Нажмите на операцию, чтобы изменить</div></section>`}

function monthLabel(month){const label=new Date(month+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long',year:'numeric'}).replace(/ г\.$/,'');return label.charAt(0).toUpperCase()+label.slice(1)}
function carryRow(month){const r=monthlyReport(state,month);const first=reportMonths(state).at(-1);return `<div class="carry-row"><span class="emoji">↪</span><span class="entry-info"><strong>${month===first?'Начальный остаток':'Остаток с прошлого месяца'}</strong><small>На ${formatDate(month+'-01')} · не считается доходом</small></span><strong>${rub(r.opening)}</strong></div>`}
function reportStats(r){return `<div class="report-stats"><div><span>На начало месяца</span><strong>${rub(r.opening)}</strong></div><div class="stat-income"><span>Доходы</span><strong>+${rub(r.income)}</strong></div><div class="stat-expense"><span>Расходы</span><strong>−${rub(r.expense)}</strong></div><div><span>Долги: поступило / выдано</span><strong>${rub(r.debtIn)} / ${rub(r.debtOut)}</strong></div><div class="stat-closing"><span>На конец${r.month===currentMonth()?' · текущий остаток':''}</span><strong>${rub(r.closing)}</strong></div></div>`}
function reports(){const selected=route.startsWith('reports/')?route.slice(8):'';return `${selected?act('navigate','← Все отчёты','back','data-route="reports"'):''}${header(selected?monthLabel(selected):'Отчёты','КАЖДЫЙ МЕСЯЦ — СВОЯ ИСТОРИЯ')}<div class="report-search"><span aria-hidden="true">⌕</span><input type="search" id="report-search" value="${esc(reportQuery)}" placeholder="Найти по всем отчётам, например: стрижка" aria-label="Поиск по всем отчётам" autocomplete="off"></div><div class="report-controls">${[['all','Все'],['income','Доходы'],['expense','Расходы'],['debt','Долги']].map(([id,label])=>act('report-filter',label,`chip ${reportFilter===id?'active':''}`,`data-value="${id}"`)).join('')}</div><div id="report-body">${reportBody()}</div>`}
function reportBody(){const selected=route.startsWith('reports/')?route.slice(8):'';
 if(reportQuery.trim()){const found=searchEntries(state,reportQuery,reportFilter);const groups=[...new Set(found.map(e=>monthKey(e.date)))];return `<div class="section-title"><h2>Результаты по всем месяцам</h2><span class="muted">Найдено: ${found.length}</span></div>${groups.map(month=>`<section class="search-month"><div class="section-title">${act('report-month',monthLabel(month)+' →','text-button',`data-month="${month}"`)}</div><div class="history-list">${found.filter(e=>monthKey(e.date)===month).map(row).join('')}</div></section>`).join('')||'<div class="empty">Ничего не найдено. Попробуйте название категории, описание или имя.</div>'}`}
 if(selected){const r=monthlyReport(state,selected),entries=searchEntries(state,'',reportFilter,selected);return `${reportStats(r)}<p class="help">Остаток переносится автоматически. Долги меняют баланс и показаны отдельно от доходов и расходов.</p><section class="history"><div class="history-list">${carryRow(selected)}${entries.map(row).join('')||'<div class="empty">Нет операций этого типа за месяц</div>'}</div><div class="history-foot">Нажмите на операцию, чтобы изменить её. Отчёт и остатки пересчитаются.</div></section>`}
 const months=reportMonths(state);return `<p class="help">Выберите месяц, чтобы посмотреть операции. Остаток переходит в следующий месяц автоматически.</p><div class="report-months">${months.map(month=>{const r=monthlyReport(state,month),count=searchEntries(state,'',reportFilter,month).length;return `<button class="month-card" data-action="report-month" data-month="${month}"><div class="panel-head"><h2>${monthLabel(month)}</h2><span class="pill">${month===currentMonth()?'Текущий месяц':'Отчёт'} ↗</span></div><p class="month-count">Операций: ${count}</p><div class="month-totals"><span class="positive">Доходы<strong>+${rub(r.income)}</strong></span><span class="negative">Расходы<strong>−${rub(r.expense)}</strong></span></div><div class="month-footer"><span>Остаток на конец месяца</span><strong>${rub(r.closing)}</strong></div></button>`}).join('')}</div>`
}
function renderReportBody(){const el=$('#report-body');if(el)el.innerHTML=reportBody()}
document.addEventListener('input',e=>{if(e.target.id==='report-search'){reportQuery=e.target.value;renderReportBody()}});
function preview(p){const days=daysUntil(p.date);return `<div class="plan-preview" role="button" tabindex="0" data-action="pay" data-id="${p.id}"><div class="preview-top"><span class="emoji">${esc(emoji(p.category))}</span><div class="preview-info"><strong>${esc(p.title)}</strong><span>${formatDate(p.date)}${p.monthly?' · ежемесячно':''}</span></div><div class="preview-amount">${rub(p.amount)}</div></div><div class="status-line"><span class="status ${urgency(p.date)}">${days<0?'Просрочено на '+Math.abs(days)+' дн.':days===0?'Сегодня':'Через '+days+' дн.'}</span><span>Оплатить ↗</span></div></div>`}
function home(){const report=monthlyReport(state,currentMonth());const upcoming=state.plans.filter(isReminder).sort((a,b)=>a.date.localeCompare(b.date));return `${header('Всё под контролем <span>🌿</span>')}<div class="dashboard"><div><section class="balance-card"><div class="small-label">Общий баланс <span style="float:right;font-size:10px">RUB ⌄</span></div><div class="balance-number">${rub(balance(state))}</div><div class="balance-bottom"><div><span>Запланировано</span><strong>${rub(planned(state))}</strong></div><div><span>Свободно после планов</span><strong>${rub(balance(state)-planned(state))}</strong></div></div></section><div class="totals"><div class="total"><div class="total-label"><span class="total-arrow">↙</span> Доходы</div><div class="total-value">+${rub(report.income)}</div><div class="total-sub">${monthLabel(currentMonth())}</div></div><div class="total expense"><div class="total-label"><span class="total-arrow">↗</span> Расходы</div><div class="total-value">−${rub(report.expense)}</div><div class="total-sub">${monthLabel(currentMonth())}</div></div></div><div class="section-title"><h2>Быстрый доступ</h2><span class="muted" style="font-size:10px">Всё на своих местах</span></div><div class="shortcut-grid"><button class="shortcut" data-action="navigate" data-route="debts"><span class="chevron">↗</span><span class="shortcut-icon">♧</span><strong>Долги</strong><p>Кто, кому и сколько</p></button><button class="shortcut" data-action="navigate" data-route="plans"><span class="chevron">↗</span><span class="shortcut-icon">▦</span><strong>Планы и платежи</strong><p>На сегодня и на потом</p></button></div>${act('entry','<b>+</b> Добавить операцию','primary add-main')}</div><div class="right-col"><section class="upcoming"><div class="upcoming-head"><h2>На горизонте</h2><span class="badge">${upcoming.length}</span></div><p class="upcoming-intro">Ближайшие планы. Без неожиданностей.</p><div class="preview-items">${upcoming.slice(0,3).map(preview).join('')||'<div class="empty">Пока никаких платежей 🌱</div>'}</div><div class="upcoming-total"><span>Всего запланировано</span><strong>${rub(planned(state))}</strong></div>${act('navigate','Все планы <span>→</span>','text-button wide','data-route="plans"')}</section><p class="quote">Не обязательно всё сразу.<br>Главное — понимать, куда идёшь.</p></div></div>${historySection()}`}
function debtCard(d){const info=debtSummary(state,d.id),closed=info.principal>0&&info.remaining===0;return `<button type="button" class="panel debt-card" data-action="debt-menu" data-id="${esc(d.id)}" aria-label="Долг: ${esc(d.person)}, ${rub(info.principal)}, ${closed?'закрыт':'остаток '+rub(info.remaining)}"><span class="debt-card-head"><strong>🤝 ${esc(d.person)}</strong><span class="debt-menu-dots" aria-hidden="true">⋯</span></span><span class="debt-card-meta">${info.date?formatDate(info.date,true):'Без операций'} · ${d.lent?'Я дал в долг':'Я взял в долг'}</span><span class="debt-card-amount">${rub(info.principal)}</span>${info.note?`<span class="debt-card-note">${esc(info.note)}</span>`:''}<span class="debt-card-bottom"><span>Возвращено<strong>${rub(info.returned)}</strong></span><span>Осталось<strong>${rub(info.remaining)}</strong></span><span class="debt-card-status ${closed?'is-closed':''}">${closed?'✓ Закрыт':info.returned>0?'Частично':'Открыт'}</span></span>${closed&&info.closedDate?`<span class="debt-closed-date">Погашен ${formatDate(info.closedDate,true)}</span>`:''}</button>`}
function debts(){return `${header('Долги','ПРОЗРАЧНО И ПРОСТО')}<div class="toolbar-row"><p class="help">На карточке — сумма сделки и остаток.<br>Нажмите на долг, чтобы открыть действия.</p>${act('new-debt','+ Новый долг','primary')}</div><div class="debt-cards">${state.debts.map(debtCard).join('')||'<div class="empty">Никаких долгов. Хорошее начало.</div>'}</div>`}
function debtDetail(id){const d=state.debts.find(d=>d.id===id);if(!d)return debts();const info=debtSummary(state,id),entries=[...info.entries].sort((a,b)=>b.date.localeCompare(a.date)||(b.created||0)-(a.created||0));return `${act('navigate','← Все долги','back','data-route="debts"')}${header(esc(d.person),'ОПЕРАЦИИ ПО ДОЛГУ')}${debtCard(d)}<h2 style="margin:25px 0 15px">${d.lent?'Выдача и возвраты':'Получение и погашения'}</h2><div class="history-list">${entries.map(row).join('')||'<div class="empty">Операций пока нет</div>'}</div>`}
function debtMenu(id){const d=state.debts.find(d=>d.id===id);if(!d)return;const info=debtSummary(state,id);open(esc(d.person),`<div class="debt-menu-summary"><span>${d.lent?'Я дал в долг':'Я взял в долг'}${info.date?' · '+formatDate(info.date,true):''}</span><strong>${rub(info.principal)}</strong><p>Возвращено ${rub(info.returned)} · Осталось ${rub(info.remaining)}</p>${info.note?`<p>${esc(info.note)}</p>`:''}</div><div class="debt-menu-actions">${info.remaining>0?act('repay','Погасить долг','primary',`data-id="${esc(id)}"`):''}${act('debt','Открыть операции','secondary',`data-id="${esc(id)}"`)}${act('edit-debt','Редактировать','secondary',`data-id="${esc(id)}"`)}${act('delete-debt','Удалить','danger',`data-id="${esc(id)}"`)}</div>`)}
function plans(){const active=state.plans.filter(isReminder).sort((a,b)=>a.date.localeCompare(b.date));const later=state.plans.filter(p=>!p.paid&&!isReminder(p)).sort((a,b)=>a.date.localeCompare(b.date));return `${header('Планы и платежи','С ЗАБОТОЙ О БУДУЩЕМ')}<div class="toolbar-row"><div><div class="small-label">Нужно отложить</div><div class="debt-total">${rub(planned(state))}</div></div>${act('plan','+ Новый план','primary')}</div><p class="help">Напоминания за 10 дней — на главной. Зелёный: больше 5 дней, оранжевый: 3–5 дней, красный: 2 дня или меньше. Уведомлений вне приложения пока нет.</p>${active.map(p=>`<section class="panel">${preview(p)}${p.note?`<p>${esc(p.note)}</p>`:''}<div class="actions">${act('pay','Оплатить','primary',`data-id="${p.id}"`)}${act('plan','Изменить','secondary',`data-id="${p.id}"`)}</div></section>`).join('')||'<div class="empty">Вы всё оплатили. Можно выдохнуть 🌿</div>'}${later.length?'<h2 style="margin:30px 0 15px">Следующие месяцы</h2><p class="help">Эти платежи пока не требуют внимания. Напомним за 10 дней до срока.</p>'+later.map(p=>`<section class="panel"><div class="panel-head"><h3>${esc(p.title)}</h3><span>${rub(p.amount)}</span></div><p>${formatDate(p.date)} · ежемесячно</p><div class="actions">${act('plan','Изменить график','secondary',`data-id="${p.id}"`)}</div></section>`).join(''):''}${state.plans.some(p=>p.paid)?'<h2 style="margin:30px 0 15px">Завершённые планы</h2>'+state.plans.filter(p=>p.paid).map(p=>`<section class="panel"><div class="panel-head"><span>✓ ${esc(p.title)}</span>${act('plan','Открыть','text-button',`data-id="${p.id}"`)}</div><p>${rub(p.amount)} · ${formatDate(p.date)}</p></section>`).join(''):''}`}
function settings(){return `${header('Настройки','ВАШ КОШЕЛЁК — ВАШИ ПРАВИЛА')}<div class="install-note"><span>↗</span><div><strong>Всегда под рукой</strong><br>На iPhone откройте сайт в Safari → «Поделиться» → «На экран Домой». После первого открытия приложение работает и без интернета.</div></div><div class="settings-grid"><section class="panel"><h3>Начальный баланс</h3><p>Сколько денег было до первой операции.</p><div class="debt-total">${rub(state.opening)}</div>${act('opening','Изменить баланс')}</section><section class="panel"><h3>Сохранение данных</h3><p>Данные остаются в этом браузере. Синхронизации между устройствами нет. Экспорт сохранит резервную копию.</p><div class="actions">${act('export','Экспорт JSON')}${act('import','Импорт JSON')}</div><input id="import-file" type="file" accept="application/json,.json" hidden></section></div><div class="category-groups">${[false,true].map(income=>`<section class="panel category-group ${income?'category-income':'category-expense'}" aria-label="Категории: ${income?'Доходы':'Расходы'}"><div class="panel-head"><h3>${income?'Категории доходов':'Категории расходов'}</h3>${act('category',income?'+ Добавить доход':'+ Добавить расход','text-button',`data-income="${income}"`)}</div>${state.categories.filter(c=>c.income===income).map(c=>`<div class="setting-row"><span>${esc(c.emoji)} ${esc(c.name)}</span>${act('category','Изменить','text-button',`data-id="${c.id}"`)}</div>`).join('')||'<p>Пока нет категорий</p>'}</section>`).join('')}</div><p class="help">Пять операций при первом запуске — тестовые. Их можно изменить или удалить. Категории со смайликами можно создавать свои. Сохранённые операции сохраняют прежнее название категории.</p><p class="app-version">Версия 1.7 · Категории расходов и доходов разделены</p><p class="help">При удалении приложения или очистке данных Safari записи могут исчезнуть. Резервную копию можно восстановить через импорт.</p>`}
function render(){for(const sel of ['#desktop-nav','#mobile-nav'])$(sel).innerHTML=navs.map(([id,icon,label])=>`<button class="nav-item ${route===id||route.startsWith('reports/')&&id==='reports'||route.startsWith('debt/')&&id==='debts'?'active':''}" data-action="navigate" data-route="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('');$('#main').innerHTML=(readError?'<p class="error">Не удалось прочитать данные браузера. Показан тестовый пример, сохранение отключено, чтобы не перезаписать исходные данные.</p>':'')+(route.startsWith('debt/')?debtDetail(route.slice(5)):route==='debts'?debts():route==='plans'?plans():(route==='history'||route==='reports'||route.startsWith('reports/'))?reports():route==='settings'?settings():home())}
function go(r){route=r;location.hash=r;render();window.scrollTo({top:0,behavior:'instant'})}window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'home';render()});
function open(title,html){$('#modal-content').innerHTML=`<div class="modal-header"><h2>${title}</h2>${act('close','×','close','aria-label="Закрыть"')}</div>${html}`;if(!modal.open)modal.showModal()}
const errorBox='<div class="error" id="form-error" role="alert"></div>';
const field=(name,label,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const dateField=(value=day())=>field('date','Дата',value,'date','required');
const moneyField=(value='',label='Сумма, ₽')=>field('amount',label,value,'text','inputmode="decimal" autocomplete="off" required');
const footer=(label='Сохранить',remove='')=>`${errorBox}<div class="form-buttons">${remove?act(remove,'Удалить','danger'):''}<button class="primary" type="submit">${label}</button></div>`;
function entryEditor(id){const e=state.entries.find(e=>e.id===id);draft={id:e?.id||uid(),amount:e?amountText(e.amount):'',kind:e?.kind||'expense',category:e?.category||'',note:e?.note||'',date:e?.date||day(),debtId:e?.debtId,planId:e?.planId,created:e?.created||Date.now(),keypad:!e,monthly:false,future:false};drawEntry()}
function categoryOptions(income,current=''){return `<option value="">Выберите категорию</option>`+state.categories.filter(c=>c.income===income).map(c=>`<option value="${esc(c.emoji+' '+c.name)}" ${current===c.emoji+' '+c.name?'selected':''}>${esc(c.emoji+' '+c.name)}</option>`).join('')+(current&&!state.categories.some(c=>c.emoji+' '+c.name===current)?`<option selected value="${esc(current)}">${esc(current)}</option>`:'')}
function drawEntry(){const editing=state.entries.some(e=>e.id===draft.id),linked=!!draft.debtId;open(editing?'Изменить операцию':'Новая операция',`<form id="entry-form">${!linked?`<div class="segment">${act('kind','Расход',draft.kind==='expense'?'active':'','data-kind="expense"')}${act('kind','Доход',draft.kind==='income'?'active':'','data-kind="income"')}</div>`:`<span class="pill">${labelKind(draft.kind)}</span>`}<label class="amount-display"><span class="sr-only">Сумма в рублях</span><input id="entry-amount" name="amount" inputmode="decimal" autocomplete="off" placeholder="0" value="${esc(draft.amount)}" ${draft.keypad?'readonly':''}><span>₽</span></label>${draft.keypad?`<div class="keypad">${['1','2','3','4','5','6','7','8','9',',','0','⌫'].map(k=>act('key',k,'',`data-key="${k}"`)).join('')}</div><button type="button" class="primary wide" data-action="amount-done">✓ Готово</button>`:`<div class="calc-done">${act('show-keypad','Открыть клавиатуру','text-button')}</div>${!linked?`<div class="field"><div class="row-links"><span>Категория</span><span class="muted" style="font-size:10px">Свои категории — в настройках</span></div><div class="category-grid">${state.categories.filter(c=>c.income===(draft.kind==='income')).map(c=>act('choose-category',`<span>${esc(c.emoji)}</span>${esc(c.name)}`,`category-choice ${draft.category===c.emoji+' '+c.name?'active':''}`,`data-label="${esc(c.emoji+' '+c.name)}"`)).join('')}</div>${draft.category?`<p style="font-size:11px;margin:10px 0;color:#6d8861">Выбрано: ${esc(draft.category)}</p>`:''}</div>`:''}${field('note','Описание — по желанию',draft.note,'text','maxlength="300"')}${dateField(draft.date)}${!editing&&!linked&&draft.kind==='expense'?`<label class="checkbox"><input name="future" type="checkbox" ${draft.future?'checked':''}> Запланировать, пока не списывать</label><label class="checkbox"><input name="monthly" type="checkbox" ${draft.monthly?'checked':''}> Повторять каждый месяц</label>`:''}${footer(editing?'Сохранить изменения':draft.future?'Создать план':'Добавить',editing?'delete-entry':'')}`}</form>`)}
function captureDraft(){const f=$('#entry-form');if(!f)return;draft.amount=f.elements.amount.value;if(f.elements.note)draft.note=f.elements.note.value;if(f.elements.date)draft.date=f.elements.date.value;if(f.elements.monthly)draft.monthly=f.elements.monthly.checked;if(f.elements.future)draft.future=f.elements.future.checked}
function debtEditor(id){const d=state.debts.find(d=>d.id===id),info=d?debtSummary(state,id):null;open(d?'Редактировать долг':'Новый долг',`<form id="debt-form" data-id="${esc(d?.id||'')}">${field('person','Имя человека',d?.person||'','text','required maxlength="80"')}${moneyField(info?amountText(info.principal):'','Сумма долга, ₽')}<label class="field">Кто кому<select name="direction"><option value="lent" ${d?.lent!==false?'selected':''}>Я даю в долг</option><option value="borrowed" ${d?.lent===false?'selected':''}>Я беру в долг</option></select></label>${dateField(info?.date||day())}${field('note','Комментарий',info?.note||'','text','maxlength="300"')}${d&&info.returned>0?`<p class="help">Уже возвращено ${rub(info.returned)}. Новая сумма долга не может быть меньше этой суммы.</p>`:''}${footer(d?'Сохранить изменения':'Добавить долг')}</form>`)}
function repayment(id){const d=state.debts.find(d=>d.id===id);if(!d)return;const rest=remaining(state,id);open('Возврат долга',`<form id="repay-form" data-id="${id}"><p class="help">${esc(d.person)} · Осталось ${rub(rest)}</p>${moneyField(amountText(rest),'Возвращаемая сумма, ₽')}${act('full-repay','Вся сумма','secondary',`data-amount="${amountText(rest)}"`)}${dateField()}${field('note','Комментарий','','text','maxlength="300"')}${footer('Подтвердить возврат')}</form>`)}
function planEditor(id){const p=state.plans.find(p=>p.id===id);open(p?'Изменить план':'Новый план',`<form id="plan-form" data-id="${p?.id||''}">${field('title','На что откладываем?',p?.title||'','text','required maxlength="100"')}${moneyField(p?amountText(p.amount):'')}${dateField(p?.date)}<label class="field">Категория<select name="category">${categoryOptions(false,p?.category)}</select></label>${field('note','Комментарий',p?.note||'','text','maxlength="300"')}<label class="checkbox"><input type="checkbox" name="monthly" ${p?.monthly?'checked':''}> Повторять каждый месяц</label>${footer('Сохранить план',p?'delete-plan':'')}</form>`)}
function payment(id){const p=state.plans.find(p=>p.id===id);if(!p||p.paid)return;if(!isReminder(p)){toast('Напомним за 10 дней до следующего платежа');return}open('Оплатить план',`<form id="pay-form" data-id="${id}"><p class="help">${esc(p.title)} · ${formatDate(p.date)}</p>${moneyField(amountText(p.amount),'Фактическая сумма, ₽')}<p class="help">Сумму можно изменить. После подтверждения добавится расход.${p.monthly?' Следующий платёж будет запланирован через месяц.':''}</p>${footer('✓ Оплачено')}</form>`)}
function categoryEditor(id,income=false){const c=state.categories.find(c=>c.id===id);const categoryIncome=c?c.income:income;open((c?'Изменить категорию ':'Новая категория ')+(categoryIncome?'доходов':'расходов'),`<form id="category-form" data-id="${c?.id||''}" data-income="${categoryIncome}">${field('emoji','Значок — любой смайлик',c?.emoji||'✨','text','required maxlength="20"')}${field('name','Название категории',c?.name||'','text','required maxlength="40"')}${footer('Сохранить',c?'delete-category':'')}</form>`)}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`кошелёк-${day()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Резервная копия подготовлена')}
function confirmAction(title,text,callback){open(title,`<p class="help">${esc(text)}</p>${errorBox}<div class="form-buttons">${act('close','Отмена')}${act('confirm','Подтвердить','danger')}</div>`);confirmAction.callback=callback}
function success(message){modal.close();draft=null;toast(message)}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;
 if(action==='navigate'){go(button.dataset.route);return}if(action==='close'){modal.close();return}if(action==='filter'){filter=button.dataset.value;render();return}
 if(action==='report-month'){reportQuery='';reportFilter='all';go('reports/'+button.dataset.month);return}if(action==='report-filter'){reportFilter=button.dataset.value;renderReportBody();document.querySelectorAll('[data-action=report-filter]').forEach(b=>b.classList.toggle('active',b.dataset.value===reportFilter));return}
 if(action==='entry'){entryEditor(id);return}if(action==='kind'){captureDraft();draft.kind=button.dataset.kind;draft.category='';drawEntry();return}
 if(action==='key'){const k=button.dataset.key;let value=$('#entry-amount').value;if(k==='⌫')value=value.slice(0,-1);else if(k===','){if(!/[,.]/.test(value))value=(value||'0')+','}else if(value.length<14&&(!value.includes(',')||value.split(',')[1].length<2))value=(value==='0'?'':value)+k;draft.amount=value;$('#entry-amount').value=value;return}
 if(action==='amount-done'){captureDraft();if(!parse(draft.amount)){showError('Введите сумму больше нуля');toast('Введите сумму больше нуля');return}draft.keypad=false;drawEntry();return}
 if(action==='show-keypad'){captureDraft();draft.keypad=true;drawEntry();return}if(action==='choose-category'){captureDraft();draft.category=button.dataset.label;drawEntry();return}
 if(action==='new-debt'){debtEditor();return}if(action==='debt-menu'){debtMenu(id);return}if(action==='edit-debt'){debtEditor(id);return}if(action==='delete-debt'){const info=debtSummary(state,id);const delta=-info.entries.reduce((sum,e)=>sum+sign(e.kind)*e.amount,0);confirmAction('Удалить долг целиком?',`Будут удалены долг и все его операции (${info.entries.length}). Баланс ${delta===0?'не изменится':(delta>0?'увеличится':'уменьшится')+' на '+rub(Math.abs(delta))}. Месячные отчёты пересчитаются.`,()=>{if(change(()=>deleteDebt(state,id))){success('Долг и его операции удалены');if(route==='debt/'+id)go('debts')}});return}if(action==='debt'){modal.close();go('debt/'+id);return}if(action==='repay'){repayment(id);return}if(action==='full-repay'){modal.querySelector('[name=amount]').value=button.dataset.amount;return}
 if(action==='plan'){planEditor(id);return}if(action==='pay'){payment(id);return}if(action==='category'){categoryEditor(id,button.dataset.income==='true');return}
 if(action==='delete-entry'){const entryId=draft.id;confirmAction('Удалить операцию?','Баланс будет пересчитан. Если операция оплачивает план, план снова станет ожидающим.',()=>{if(change(()=>removeEntry(state,entryId)))success('Операция удалена')});return}
 if(action==='delete-plan'){const planId=$('#plan-form').dataset.id;confirmAction('Удалить план?','Записи об уже совершённых платежах останутся в истории.',()=>{if(change(()=>{state.plans=state.plans.filter(p=>p.id!==planId)}))success('План удалён')});return}
 if(action==='delete-category'){const categoryId=$('#category-form').dataset.id;confirmAction('Удалить категорию?','История операций сохранится с прежним названием.',()=>{if(change(()=>{state.categories=state.categories.filter(c=>c.id!==categoryId)}))success('Категория удалена')});return}
 if(action==='confirm'){confirmAction.callback?.();return}
 if(action==='opening'){open('Начальный баланс',`<form id="opening-form">${moneyField(amountText(state.opening),'Баланс до первой операции, ₽')}${footer()}</form>`);return}
 if(action==='export'){exportData();return}if(action==='import'){$('#import-file').click();return}
});
document.addEventListener('keydown',e=>{if(e.target.classList.contains('plan-preview')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();payment(e.target.dataset.id)}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,fd=new FormData(form),v=k=>String(fd.get(k)||'').trim(),amount=parse(v('amount'));if(form.id!=='category-form'&&form.id!=='opening-form'&&!amount){showError('Введите корректную сумму больше нуля, максимум два знака после запятой');return}if(fd.has('date')&&!validDate(v('date'))){showError('Проверьте дату');return}
 if(form.id==='entry-form'){captureDraft();if(!draft.debtId&&!draft.category){showError('Выберите категорию');return}const editing=state.entries.find(e=>e.id===draft.id);if(change(()=>{if(draft.future){state.plans.push({id:uid(),title:draft.note||draft.category,amount,date:draft.date,anchor:Number(draft.date.slice(-2)),category:draft.category,note:draft.note,monthly:draft.monthly,paid:false})}else{putEntry(state,{...editing,id:draft.id,amount,kind:draft.kind,category:draft.category,note:draft.note,date:draft.date,created:draft.created,...(draft.debtId?{debtId:draft.debtId}:{}),...(draft.planId?{planId:draft.planId}:{})});if(!editing&&draft.monthly){const anchor=Number(draft.date.slice(-2));state.plans.push({id:uid(),title:draft.note||draft.category,amount,date:nextMonth(draft.date,anchor),anchor,category:draft.category,note:draft.note,monthly:true,paid:false})}}}))success(draft.future?'План добавлен':'Операция сохранена');return}
 if(form.id==='debt-form'){if(!v('person'))return;const existing=form.dataset.id;if(change(()=>{if(existing){editDebt(state,existing,{person:v('person'),amount,date:v('date'),note:v('note'),lent:v('direction')==='lent'})}else{const d={id:uid(),person:v('person'),lent:v('direction')==='lent'};state.debts.push(d);putEntry(state,{id:uid(),amount,kind:d.lent?'lent':'borrowed',date:v('date'),category:'🤝 '+d.person,note:v('note'),debtId:d.id,created:Date.now()})}}))success(existing?'Долг обновлён':'Долг добавлен');return}
 if(form.id==='repay-form'){const d=state.debts.find(d=>d.id===form.dataset.id);if(amount>remaining(state,d.id)){showError('Нельзя вернуть больше остатка долга');return}if(change(()=>putEntry(state,{id:uid(),amount,kind:d.lent?'returned':'repaid',date:v('date'),category:'🤝 '+d.person,note:v('note')||'Возврат долга',debtId:d.id,created:Date.now()})))success('Возврат сохранён');return}
 if(form.id==='plan-form'){if(!v('title'))return;if(change(()=>{const id=form.dataset.id||uid(),old=state.plans.find(p=>p.id===id),p={id,title:v('title'),amount,date:v('date'),anchor:Number(v('date').slice(-2)),category:v('category')||'📅 Платежи',note:v('note'),monthly:fd.has('monthly'),paid:old?.paid||false};state.plans=state.plans.filter(p=>p.id!==id).concat(p)}))success('План сохранён');return}
 if(form.id==='pay-form'){if(change(()=>payPlan(state,form.dataset.id,amount)))success('Платёж записан');return}
 if(form.id==='category-form'){if(!v('name')||!v('emoji'))return;const segmented=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('ru',{granularity:'grapheme'}).segment(v('emoji'))][0].segment:emoji(v('emoji'));if(change(()=>{const id=form.dataset.id||uid();state.categories=state.categories.filter(c=>c.id!==id).concat({id,name:v('name'),emoji:segmented,income:form.dataset.income==='true'})}))success('Категория сохранена');return}
 if(form.id==='opening-form'){const value=v('amount')==='0'?0:amount;if(value===null){showError('Укажите ноль или положительную сумму');return}if(change(()=>{state.opening=value}))success('Начальный баланс сохранён')}
});
document.addEventListener('change',async e=>{if(e.target.id!=='import-file')return;const file=e.target.files[0];if(!file)return;if(file.size>5000000){toast('Файл слишком большой, максимум 5 МБ');return}try{const imported=JSON.parse(await file.text());if(!valid(imported))throw Error('Неверный формат резервной копии');confirmAction('Восстановить резервную копию?','Текущие записи будут заменены данными из файла. Рекомендуем сначала экспортировать текущий кошелёк.',()=>{if(change(()=>{state=imported}))success('Данные восстановлены')})}catch(err){toast(err.message)}e.target.value=''});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!modal.open&&document.activeElement?.id!=='report-search')render()});
setInterval(()=>{if(!document.hidden&&!modal.open&&document.activeElement?.id!=='report-search')render()},60000);
render();
if('serviceWorker'in navigator){
 let updatePending=false,reloading=false;const wasControlled=!!navigator.serviceWorker.controller;
 const reloadUpdate=()=>{if(reloading)return;if(modal.open){updatePending=true;return}reloading=true;location.reload()};
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(wasControlled)reloadUpdate()});
 modal.addEventListener('close',()=>{if(updatePending)reloadUpdate()});
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{
  reg.update().catch(()=>{});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)reg.update().catch(()=>{})});
 }).catch(()=>toast('Офлайн-режим пока недоступен'));
}

